/// <summary>
/// Starts a read scope for one read on this async flow, such as one tool call, and enters the read's frame: until
/// the scope ends, every decision on the flows inside it is made at <see cref="SecurityLabel.SystemHigh"/>. When it
/// ends it observes what the read reported, or <see cref="SecurityLabel.SystemHigh"/>, into every frame of the chain
/// it was begun on, and then, on the flow whose head it is, restores the frame it was begun in.
/// </summary>
/// <returns>The scope. Call <see cref="ReadScope.Complete"/> when the read returns, and dispose it.</returns>
/// <remarks>Dispose the scope in a <c>using</c> block on the flow that began it, in order, as for
/// <see cref="Enter"/>: a flow that never ends the read as its head stays inside the read's frame, at SystemHigh.
/// Work created and started inside the read keeps the read's frame, at SystemHigh, for its whole life.</remarks>
public static ReadScope BeginRead()
{
    var chain = Active.Value;
    var read = Frame.ForRead(chain);
    Active.Value = read;
    return new ReadScope(chain, read);
}

