private async Task<HttpResponseMessage> FollowAsync(HttpRequestMessage request, CancellationToken cancellationToken)
{
    EnsureEvaluated(request);
    var response = await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
    var redirects = 0;
    while (TryGetRedirect(request, response, out var location))
    {
        redirects++;
        if (redirects > _settings.MaxAutomaticRedirections)
            break;

        if (cancellationToken.IsCancellationRequested)
        {
            response.Dispose();
            cancellationToken.ThrowIfCancellationRequested();
        }

        var status = response.StatusCode;
        response.Dispose();
        ApplyRedirect(request, status, location);
        EvaluateHop(request);
        response = await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
    }

    return response;
}

mutation.new:
private async Task<HttpResponseMessage> FollowAsync(HttpRequestMessage request, CancellationToken cancellationToken)
{
    EnsureEvaluated(request);
    var response = await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
    var redirects = 0;
    while (TryGetRedirect(request, response, out var location))
    {
        redirects++;
        if (redirects > _settings.MaxAutomaticRedirections + 1)
            break;

        if (cancellationToken.IsCancellationRequested)
        {
            response.Dispose();
            cancellationToken.ThrowIfCancellationRequested();
        }

        var status = response.StatusCode;
        response.Dispose();
        ApplyRedirect(request, status, location);
        EvaluateHop(request);
        response = await base.SendAsync(request, cancellationToken).ConfigureAwait(false);
    }

    return response;
}

